// todo store
const items = [];
export function add(text) { items.push({ text, done: false }); return items.length; }
export function list() { return items.map((t, i) => `${i + 1}. [${t.done ? 'x' : ' '}] ${t.text}`); }
export function complete(n) { items[n - 1].done = true; }
